// First on-board UI prototype: text and selection frames are generated by FPGA.
// Portraits and article assets will replace the temporary silhouettes later.
module medal_ui_osd (
    input  wire        clk,
    input  wire        rst,
    input  wire        vs,
    input  wire        de,
    input  wire [1:0]  level,
    input  wire [4:0]  person_index,
    input  wire [2:0]  section_index,
    input  wire [7:0]  page_index,
    input  wire        quiz_option,
    input  wire        quiz_revealed,
    input  wire        auto_mode,
    input  wire        prompt_visible,
    input  wire [23:0] rgb_in,
    output reg  [23:0] rgb_out
);

`include "medal_font.vh"

reg [9:0] x;
reg [8:0] y;
reg de_q;
reg vs_q;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        x <= 10'd0;
        y <= 9'd0;
        de_q <= 1'b0;
        vs_q <= 1'b0;
    end else begin
        de_q <= de;
        vs_q <= vs;
        if (vs != vs_q) begin
            x <= 10'd0;
            y <= 9'd0;
        end else begin
            if (de)
                x <= x + 10'd1;
            else
                x <= 10'd0;
            if (de_q && !de)
                y <= y + 9'd1;
        end
    end
end

function glyph_pixel;
    input [7:0] glyph_id;
    input [3:0] glyph_x;
    input [3:0] glyph_y;
    reg [15:0] bits;
    begin
        bits = medal_glyph_row(glyph_id, glyph_y);
        glyph_pixel = bits[15 - glyph_x];
    end
endfunction

reg        home_card;
reg [1:0]  home_col;
reg [1:0]  home_row;
reg [9:0]  card_left;
reg [8:0]  card_top;
wire [4:0] card_index = {home_row, 2'b00} + {3'd0, home_col};
wire [9:0] card_dx = x - card_left;
wire [8:0] card_dy = y - card_top;

always @* begin
    home_card = 1'b0;
    home_col  = 2'd0;
    home_row  = 2'd0;
    card_left = 10'd0;
    card_top  = 9'd0;
    if      (x >= 10'd16  && x < 10'd164) begin home_col = 2'd0; card_left = 10'd16;  home_card = 1'b1; end
    else if (x >= 10'd168 && x < 10'd316) begin home_col = 2'd1; card_left = 10'd168; home_card = 1'b1; end
    else if (x >= 10'd320 && x < 10'd468) begin home_col = 2'd2; card_left = 10'd320; home_card = 1'b1; end
    else if (x >= 10'd472 && x < 10'd620) begin home_col = 2'd3; card_left = 10'd472; home_card = 1'b1; end
    else home_card = 1'b0;
    if      (y >= 9'd80  && y < 9'd168) begin home_row = 2'd0; card_top = 9'd80;  end
    else if (y >= 9'd172 && y < 9'd260) begin home_row = 2'd1; card_top = 9'd172; end
    else if (y >= 9'd264 && y < 9'd352) begin home_row = 2'd2; card_top = 9'd264; end
    else if (y >= 9'd356 && y < 9'd444) begin home_row = 2'd3; card_top = 9'd356; end
    else home_card = 1'b0;
    if (card_index >= 5'd13)
        home_card = 1'b0;
end

wire home_border = card_dx < 10'd3 || card_dx >= 10'd145 ||
                   card_dy < 9'd3 || card_dy >= 9'd85;
wire home_name_area = home_card && card_dx >= 10'd40 && card_dx < 10'd88 &&
                      card_dy >= 9'd57 && card_dy < 9'd73;
wire [9:0] home_name_x = card_dx - 10'd40;
wire [8:0] home_name_y = card_dy - 9'd57;
wire home_name_pixel = home_name_area &&
    glyph_pixel(medal_person_char(card_index, {1'b0, home_name_x[5:4]}),
                home_name_x[3:0], home_name_y[3:0]);

wire [9:0] title_x = x - 10'd240;
wire [8:0] title_y = y - 9'd18;
wire title_area = x >= 10'd240 && x < 10'd400 &&
                  y >= 9'd18 && y < 9'd50;
wire title_pixel = title_area &&
    glyph_pixel(medal_title_char(1'b0, title_x[7:5]),
                title_x[4:1], title_y[4:1]);

reg       menu_card;
reg [1:0] menu_index;
reg [9:0] menu_left;
reg [8:0] menu_top;
wire [9:0] menu_dx = x - menu_left;
wire [8:0] menu_dy = y - menu_top;

always @* begin
    menu_card = 1'b0;
    menu_index = 2'd0;
    menu_left = 10'd0;
    menu_top = 9'd0;
    if (x >= 10'd40 && x < 10'd308) begin
        menu_left = 10'd40;
        menu_card = 1'b1;
    end else if (x >= 10'd332 && x < 10'd600) begin
        menu_left = 10'd332;
        menu_index = 2'd1;
        menu_card = 1'b1;
    end
    if (y >= 9'd230 && y < 9'd318) begin
        menu_top = 9'd230;
    end else if (y >= 9'd334 && y < 9'd422) begin
        menu_top = 9'd334;
        menu_index = menu_index + 2'd2;
    end else menu_card = 1'b0;
end

wire menu_border = menu_dx < 10'd3 || menu_dx >= 10'd265 ||
                   menu_dy < 9'd3 || menu_dy >= 9'd85;
wire [9:0] menu_text_x = menu_dx - 10'd92;
wire [8:0] menu_text_y = menu_dy - 9'd36;
wire menu_text_area = menu_card && menu_dx >= 10'd92 && menu_dx < 10'd156 &&
                      menu_dy >= 9'd36 && menu_dy < 9'd52;
wire menu_text_pixel = menu_text_area &&
    glyph_pixel(medal_section_char(menu_index, {1'b0,menu_text_x[5:4]}),
                menu_text_x[3:0], menu_text_y[3:0]);

wire [9:0] person_name_x = x - 10'd80;
wire [8:0] person_name_y = y - 9'd118;
wire person_name_area = x >= 10'd80 && x < 10'd176 &&
                        y >= 9'd118 && y < 9'd150;
wire person_name_pixel = person_name_area &&
    glyph_pixel(medal_person_char(person_index, {1'b0,person_name_x[6:5]}),
                person_name_x[4:1], person_name_y[4:1]);

wire [9:0] article_x = x - 10'd240;
wire [8:0] article_y = y - 9'd230;
wire article_area = x >= 10'd240 && x < 10'd400 &&
                    y >= 9'd230 && y < 9'd262;
wire article_pixel = article_area &&
    glyph_pixel(medal_title_char(1'b1, article_x[7:5]),
                article_x[4:1], article_y[4:1]);

wire [9:0] section_x = x - 10'd300;
wire [8:0] section_y = y - 9'd118;
wire section_heading_area = x >= 10'd300 && x < 10'd428 &&
                            y >= 9'd118 && y < 9'd150;
wire section_heading_pixel = section_heading_area &&
    glyph_pixel(medal_section_char(section_index[1:0], {1'b0,section_x[6:5]}),
                section_x[4:1], section_y[4:1]);

reg        pilot_line_area;
reg [1:0]  pilot_line;
reg [8:0]  pilot_line_top;
always @* begin
    pilot_line_area = 1'b1;
    pilot_line = 2'd0;
    pilot_line_top = 9'd170;
    if      (y >= 9'd170 && y < 9'd202) begin pilot_line = 2'd0; pilot_line_top = 9'd170; end
    else if (y >= 9'd226 && y < 9'd258) begin pilot_line = 2'd1; pilot_line_top = 9'd226; end
    else if (y >= 9'd282 && y < 9'd314) begin pilot_line = 2'd2; pilot_line_top = 9'd282; end
    else if (y >= 9'd338 && y < 9'd370) begin pilot_line = 2'd3; pilot_line_top = 9'd338; end
    else pilot_line_area = 1'b0;
end
wire [9:0] pilot_x = x - 10'd64;
wire [8:0] pilot_y = y - pilot_line_top;
wire pilot_text_area = pilot_line_area && x >= 10'd64 && x < 10'd576;
wire pilot_text_pixel = pilot_text_area &&
    glyph_pixel(medal_pilot_char(section_index[1:0], page_index[0], pilot_line,
                                  pilot_x[8:5]), pilot_x[4:1], pilot_y[4:1]);

// The contribution pilot page uses a TF image on the left and text on the
// right; glyphs are 16x16 here to fit 16 Chinese characters in 256 pixels.
wire [7:0] side_text_x = x - 10'd336;
wire side_text_pixel = pilot_line_area && y < pilot_line_top + 9'd16 &&
    x >= 10'd336 && x < 10'd592 &&
    glyph_pixel(medal_pilot_char(section_index[1:0], page_index[0], pilot_line,
                                  side_text_x[7:4]), side_text_x[3:0], pilot_y[3:0]);

wire [9:0] feedback_x = x - 10'd250;
wire [8:0] feedback_y = y - 9'd392;
wire feedback_area = x >= 10'd250 && x < 10'd378 &&
                     y >= 9'd392 && y < 9'd424;
wire feedback_pixel = feedback_area &&
    glyph_pixel(medal_feedback_char(quiz_option, {1'b0,feedback_x[6:5]}),
                feedback_x[4:1], feedback_y[4:1]);

wire [7:0] auto_x = x - 10'd488;
wire [5:0] auto_y = y - 9'd18;
wire auto_pixel = auto_mode && x >= 10'd488 && x < 10'd616 &&
                  y >= 9'd18 && y < 9'd50 &&
    glyph_pixel(medal_auto_char({2'b00, auto_x[6:5]}), auto_x[4:1], auto_y[4:1]);

wire [8:0] prompt_x = x - 10'd160;
wire [5:0] prompt_y = y - 9'd18;
wire prompt_pixel = prompt_visible && x >= 10'd160 && x < 10'd480 &&
                    y >= 9'd18 && y < 9'd50 &&
    glyph_pixel(medal_prompt_char(prompt_x[8:5]), prompt_x[4:1], prompt_y[4:1]);

always @* begin
    rgb_out = rgb_in;
    if (de) begin
        rgb_out = 24'h0B1325;
        if (y < 9'd64)
            rgb_out = 24'h132B45;
        if (y >= 9'd62 && y < 9'd66)
            rgb_out = 24'hD6A84C;
        if (title_pixel)
            rgb_out = 24'hFFF5D7;

        if (level == 2'd0 && home_card) begin
            rgb_out = (card_index == person_index) ? 24'h30445D : 24'h1B3048;
            if (home_border)
                rgb_out = (card_index == person_index) ? 24'hF2C35B : 24'h3A5670;
            // A simple silhouette marks the future portrait position.
            if (card_dx >= 10'd61 && card_dx < 10'd85 &&
                card_dy >= 9'd12 && card_dy < 9'd36)
                rgb_out = 24'h728AA3;
            if (card_dx >= 10'd47 && card_dx < 10'd99 &&
                card_dy >= 9'd37 && card_dy < 9'd54)
                rgb_out = 24'h728AA3;
            if (home_name_pixel)
                rgb_out = 24'hFFFFFF;
        end

        if (level == 2'd1) begin
            if (x >= 10'd40 && x < 10'd600 && y >= 9'd88 && y < 9'd190)
                rgb_out = 24'h1B3048;
            if (person_name_pixel)
                rgb_out = 24'hFFF5D7;
            if (menu_card) begin
                rgb_out = (menu_index == section_index[1:0]) ? 24'h30445D : 24'h1B3048;
                if (menu_border)
                    rgb_out = (menu_index == section_index[1:0]) ? 24'hF2C35B : 24'h3A5670;
                if (menu_text_pixel)
                    rgb_out = 24'hFFFFFF;
            end
        end

        if (level == 2'd2) begin
            if (x >= 10'd40 && x < 10'd600 && y >= 9'd92 && y < 9'd430)
                rgb_out = 24'h1B3048;
            if (person_index == 5'd0) begin
                if (section_index == 3'd1 && x >= 10'd40 && x < 10'd300 &&
                    y >= 9'd150 && y < 9'd410)
                    rgb_out = rgb_in;
                if (section_index == 3'd1 && x >= 10'd38 && x < 10'd302 &&
                    y >= 9'd148 && y < 9'd412 &&
                    (x < 10'd40 || x >= 10'd300 || y < 9'd150 || y >= 9'd410))
                    rgb_out = 24'hF2C35B;
                if (section_index == 3'd3 &&
                    x >= 10'd56 && x < 10'd584 &&
                    ((y >= 9'd274 && y < 9'd322 && quiz_option == 1'b0) ||
                     (y >= 9'd330 && y < 9'd378 && quiz_option == 1'b1)))
                    rgb_out = 24'h30445D;
                if (section_index == 3'd1 ? side_text_pixel : pilot_text_pixel)
                    rgb_out = 24'hFFFFFF;
                if (section_index != 3'd3 && y >= 9'd390 && y < 9'd400 &&
                    ((x >= 10'd299 && x < 10'd309) ||
                     (x >= 10'd331 && x < 10'd341)))
                    rgb_out = ((x < 10'd320) == (page_index == 8'd0))
                                  ? 24'hF2C35B : 24'h3A5670;
                if (section_index == 3'd3 && quiz_revealed && feedback_pixel)
                    rgb_out = quiz_option ? 24'hFF8B8B : 24'h8DE4A3;
                if (person_name_pixel || section_heading_pixel)
                    rgb_out = 24'hFFF5D7;
            end else if (article_pixel) begin
                rgb_out = 24'hFFF5D7;
            end
        end

        if (auto_mode && x >= 10'd480 && x < 10'd624 &&
            y >= 9'd10 && y < 9'd58)
            rgb_out = 24'h245A6B;
        if (auto_pixel)
            rgb_out = 24'hFFFFFF;
        if (prompt_visible && x >= 10'd112 && x < 10'd624 &&
            y >= 9'd10 && y < 9'd58)
            rgb_out = 24'hA12D35;
        if (prompt_pixel)
            rgb_out = 24'hFFFFFF;
    end
end

endmodule
